// ===== CONFIGURAÇÃO (pode editar com calma) =====
const DIAS_A_FRENTE = 1;                 // 1 = gera as postagens de AMANHÃ (o fluxo roda à noite)
const HORARIOS = { telegram: 8, facebook: 10, instagram: 12, email: 17 }; // hora de Brasília em que cada uma deve sair
const EMAIL_DIAS = [2, 5];               // dias com e-mail marketing: 0=dom 1=seg 2=ter 3=qua 4=qui 5=sex 6=sáb
const SITE = 'https://www.igreja.eco.br';

// Um tema por dia da semana. "gancho" é o texto de reserva usado se a IA estiver fora do ar.
const TEMAS = {
  1: { nome: 'Oficina Digital', caminho: '/oficina', cor: 'azul',
       foco: 'convite para pessoas que querem trabalhar como operadores digitais, por tarefa, com treinamento dentro da própria tarefa. Nunca prometa renda.',
       gancho: 'Quer aprender fazendo? Na Oficina Digital você executa tarefas reais, com a IA ensinando enquanto trabalha, e acumula Pontos Oficina.',
       arte: 'Aprenda fazendo na Oficina Digital', apoio: 'Tarefas reais, treinamento embutido' },
  2: { nome: 'Ateliê Sob Medida', caminho: '/atelie', cor: 'azul',
       foco: 'serviços digitais para comércios: site ou página de vendas, agente de WhatsApp com IA e automação de processos. Fale de problemas reais do pequeno comerciante.',
       gancho: 'Seu comércio perde vendas por demorar a responder no WhatsApp? No Ateliê Sob Medida montamos site, atendimento com IA e automações sob medida.',
       arte: 'Seu comércio atendendo 24 horas', apoio: 'Site, WhatsApp com IA e automação sob medida' },
  3: { nome: 'Calçados de fábrica de Franca', caminho: '/calcados', cor: 'terra',
       foco: 'calçados e acessórios direto de fábrica de Franca-SP. Não invente preços, prazos, frete nem descontos; convide a conhecer o catálogo.',
       gancho: 'Calçado de fábrica de Franca, a capital do calçado, com catálogo online. Conheça os modelos e escolha o seu.',
       arte: 'Calçado de fábrica, direto de Franca', apoio: 'Conheça o catálogo online' },
  4: { nome: 'Alimentos da floresta e agroecologia', caminho: '/', cor: 'verde',
       foco: 'agroecologia e alimentos naturais da Amazônia, com conteúdo educativo e respeitoso. Não faça nenhuma promessa de saúde, cura ou emagrecimento.',
       gancho: 'Agroecologia é cuidar da terra produzindo alimento de verdade. Acompanhe a nossa caminhada e conheça os projetos do site.',
       arte: 'Agroecologia: cuidar da terra, produzir alimento', apoio: 'Acompanhe a nossa caminhada' },
  5: { nome: 'Pontos, Fidelidade e Afiliados', caminho: '/campanha', cor: 'noite',
       foco: 'Campanha de Inauguração, Clube de Fidelidade e Programa de Afiliados (pontos por venda paga; sem pagar por cadastrar outros afiliados). Seja claro: pontos não são dinheiro e não há garantia de ganho.',
       gancho: 'Na Campanha de Inauguração do igreja.eco.br você acumula pontos e troca por produtos e projetos. Veja as regras e participe.',
       arte: 'Acumule pontos e troque por projetos', apoio: 'Campanha de Inauguração do igreja.eco.br' },
  6: { nome: 'Cursos e e-books', caminho: '/ebooks', cor: 'verde',
       foco: 'cursos e e-books práticos "como fazer", incluindo ovinocultura. Destaque o aprendizado prático e acessível; não prometa resultado financeiro.',
       gancho: 'Aprender o passo a passo muda tudo. Conheça os e-books e cursos práticos do igreja.eco.br.',
       arte: 'Aprenda o passo a passo', apoio: 'E-books e cursos práticos' },
  0: { nome: 'Comunidade Igreja Eco', caminho: '/', cor: 'noite',
       foco: 'mensagem de encorajamento e comunidade, de tom acolhedor e simples, convidando a conhecer o portal. Sem pregar política e sem prometer milagres ou ganhos.',
       gancho: 'Domingo é dia de parar, agradecer e renovar as forças. Seja bem-vindo à nossa comunidade em igreja.eco.br.',
       arte: 'Um domingo de gratidão e esperança', apoio: 'Bem-vindo à nossa comunidade' },
};

// ===== Data de Brasília (UTC-3, sem horário de verão) =====
const brasilia = new Date(Date.now() - 3 * 3600 * 1000 + DIAS_A_FRENTE * 24 * 3600 * 1000);
const dia = brasilia.getUTCDay();
const p2 = (n) => String(n).padStart(2, '0');
const dataISO = `${brasilia.getUTCFullYear()}-${p2(brasilia.getUTCMonth() + 1)}-${p2(brasilia.getUTCDate())}`;
const tema = TEMAS[dia];
const link = SITE + tema.caminho;
const comEmail = EMAIL_DIAS.includes(dia);

const prompt = `Você escreve a divulgação diária do site igreja.eco.br (portal em português do Brasil com Oficina Digital, Ateliê Sob Medida, calçados de fábrica de Franca, alimentos da floresta e cursos).

TEMA DE HOJE: ${tema.nome}
FOCO: ${tema.foco}
LINK PRINCIPAL: ${link}

REGRAS OBRIGATÓRIAS:
- Português do Brasil, tom simples, caloroso e direto, como falaria uma pessoa de verdade.
- NUNCA prometa renda, lucro, cura, emagrecimento ou resultado garantido.
- NUNCA invente preço, prazo, desconto, estoque, depoimento ou número de clientes.
- Cada texto deve terminar com um convite claro para ver o link principal.
- Facebook: 400 a 700 caracteres. Instagram: 250 a 500 caracteres, com 3 a 6 emojis. Telegram: 250 a 450 caracteres.
- "arte_titulo": frase curta e forte (no máximo 60 caracteres). "arte_subtitulo": no máximo 110 caracteres.
- Hashtags: de 4 a 8, em português, separadas por espaço, cada uma começando com #.
${comEmail ? '- E-mail: assunto de até 70 caracteres e corpo de 600 a 1000 caracteres, com saudação "Olá!" e despedida "Equipe Igreja Eco".' : '- Hoje NÃO haverá e-mail: omita o campo "email".'}

Responda SOMENTE com um JSON válido neste formato, sem comentários:
{"facebook":{"texto":"","hashtags":"","arte_titulo":"","arte_subtitulo":""},"instagram":{"texto":"","hashtags":"","arte_titulo":"","arte_subtitulo":""},"telegram":{"texto":""}${comEmail ? ',"email":{"assunto":"","texto":""}' : ''}}`;

const corpo = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.9, responseMimeType: 'application/json' },
};

return [{ json: { dataISO, dia, tema, link, comEmail, horarios: HORARIOS, corpo } }];

// Junta a resposta da IA com os horários e monta o lote para o painel.
// Se a IA falhar ou responder fora do formato, usa o texto de reserva do tema: o operador nunca fica sem postagens.
const cfg = $('Preparar pedido').first().json;
const resp = $input.first().json || {};
const { dataISO, tema, link, comEmail, horarios } = cfg;

let ia = null;
try {
  const bruto = resp.candidates[0].content.parts[0].text;
  ia = JSON.parse(String(bruto).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim());
} catch (e) {
  ia = null;
}

const limpa = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const hashtagsReserva = '#igrejaeco #igrejaecobr';
const [ano, mes, d] = dataISO.split('-');
const quando = (h) => `${dataISO}T${String(h).padStart(2, '0')}:00:00-03:00`;
const nomes = { facebook: 'Facebook', instagram: 'Instagram', telegram: 'Telegram', email: 'E-mail' };

const postagens = [];
let usouReserva = 0;
function adicionar(rede, dadosIA) {
  const ok = dadosIA && limpa(dadosIA.texto, 6000).length >= 40;
  if (!ok) usouReserva++;
  const base = {
    chave: `${dataISO}-${rede}`,
    rede,
    titulo: `${tema.nome} · ${nomes[rede]} · ${d}/${mes}${ok ? '' : ' (texto de reserva)'}`,
    link_destino: link,
    arte_tema: tema.cor,
    agendada_para: quando(horarios[rede]),
  };
  if (rede === 'email') {
    postagens.push({
      ...base,
      email_assunto: ok ? limpa(dadosIA.assunto, 120) || tema.nome : tema.nome,
      texto: ok ? limpa(dadosIA.texto, 6000) : `Olá!\n\n${tema.gancho}\n\nVeja mais em ${link}\n\nEquipe Igreja Eco`,
    });
    return;
  }
  postagens.push({
    ...base,
    texto: ok ? limpa(dadosIA.texto, 3000) : `${tema.gancho}\n\nSaiba mais: ${link}`,
    hashtags: ok ? limpa(dadosIA.hashtags, 300) || hashtagsReserva : hashtagsReserva,
    arte_titulo: ok ? limpa(dadosIA.arte_titulo, 90) || tema.arte : tema.arte,
    arte_subtitulo: ok ? limpa(dadosIA.arte_subtitulo, 160) || tema.apoio : tema.apoio,
  });
}

adicionar('telegram', ia && ia.telegram);
adicionar('facebook', ia && ia.facebook);
adicionar('instagram', ia && ia.instagram);
if (comEmail) adicionar('email', ia && ia.email);

return [{ json: { lote: dataISO, usouReserva, geradoPelaIA: !!ia, postagens } }];
